import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

public class LoanDesk {
    private static final int LOAN_DAYS = 14;
    private static final int MAX_RENEWALS = 2;
    private static final long BLOCKING_FINE_CENTS = 500;
    private static final long FINE_CENTS_PER_DAY = 25;

    public record Loan(String isbn, LocalDate dueDate, int renewals) {
        public boolean isOverdue(LocalDate today) {
            return !today.isBefore(dueDate);
        }
    }

    public record Member(String id, boolean suspended, long finesCents, boolean premium) {}

    public Loan renew(Member member, Loan loan, LocalDate today) {
        if (member.suspended()
                || loan.renewals() >= (member.premium() ? MAX_RENEWALS + 1 : MAX_RENEWALS)
                || loan.isOverdue(today)
                || member.finesCents() >= BLOCKING_FINE_CENTS) {
            throw new IllegalStateException("Loan of " + loan.isbn() + " cannot be renewed");
        }
        return new Loan(loan.isbn(), loan.dueDate().plusDays(LOAN_DAYS), loan.renewals() + 1);
    }

    /** The fine in cents: a fixed amount for every whole day late, capped at the price of the book. */
    public long fineCents(Loan loan, LocalDate returnedOn) {
        long daysLate = ChronoUnit.DAYS.between(loan.dueDate(), returnedOn);
        return daysLate * FINE_CENTS_PER_DAY;
    }
}

